struct Aggregate {
  int x;
  short y;
};

// Valid: No narrowing conversions
Aggregate a1{ 10, 5 };

// ERROR: Narrowing conversion (double to int)
// List initialization prevents potential data loss
Aggregate a2{ 10.5, 5 };

// ERROR: Narrowing conversion (int literal 33000 to short)
// 33000 exceeds SHRT_MAX
Aggregate a3{ 10, 33000 };

// C-style assignment bypasses strict list initialization rules:
// short s_fail = 33000; // Compiler warning, not hard error (implementation dependent)
